package ru.neverland.townydistricts.service;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import ru.neverland.core.SuiteState;
import ru.neverland.townydistricts.model.DistrictAssessment;
import static ru.neverland.townydistricts.model.DistrictAssessment.*;
public final class DistrictPlannerSmoke {
    static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    static DistrictPlanner.Reading ready(DistrictPlanner planner,UUID town,Input input)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);DistrictPlanner.Reading result;do{result=planner.read(town,input);if(!result.status().equals("PENDING"))return result;Thread.sleep(1);}while(System.nanoTime()<until);throw new AssertionError("calculation timed out");}
    public static void main(String[] args)throws Exception{
        var input=new Input(List.of(),List.of(),Map.of(),Set.of(),Set.of(),null,16,true,new Settings(8,Map.of()));var count=new AtomicInteger();var planner=new DistrictPlanner(value->{if(SuiteState.held())throw new AssertionError("CPU worker acquired suite state");count.incrementAndGet();return DistrictAssessment.calculate(value);});UUID town=UUID.randomUUID();
        try(var guard=SuiteState.guard()){check(planner.read(town,input).status().equals("PENDING"),"request never waits for graph calculation under suite state");}var report=ready(planner,town,input);check(report.status().equals("READY")&&report.result().rows().isEmpty()&&report.at()>0,"detached immutable result becomes available with timestamp");check(ready(planner,town,input).equals(report)&&count.get()==1,"equal snapshots reuse one completed result");
        var changed=new Input(List.of(),List.of(),Map.of(),Set.of(),Set.of(),null,16,true,new Settings(9,Map.of()));check(planner.read(town,changed).status().equals("PENDING")&&ready(planner,town,changed).result().range()==9&&count.get()==2,"changed input never presents old result as current");planner.awaitClosed();check(planner.read(town,input).status().equals("CLOSED"),"closed calculator cannot enqueue work after unload");
        var started=new CountDownLatch(1);var block=new CountDownLatch(1);var slow=new DistrictPlanner(value->{started.countDown();try{block.await();}catch(InterruptedException error){throw new CancellationException("shutdown");}return DistrictAssessment.calculate(value);});check(slow.read(UUID.randomUUID(),input).status().equals("PENDING")&&started.await(1,TimeUnit.SECONDS),"explicit slow CPU fixture started on detached worker");for(int i=0;i<16;i++)slow.read(UUID.randomUUID(),input);check(slow.read(UUID.randomUUID(),input).issue().contains("занята"),"bounded queue refuses excess work without blocking caller");try(var guard=SuiteState.guard()){check(SuiteState.tryRun("planner while CPU blocked",()->{}),"blocked derived calculation never holds suite lock");slow.prepareClose();}slow.awaitClosed();check(true,"shutdown cancels disposable derived work without waiting on region or disk");
        var world=UUID.randomUUID();var cell=new ru.neverland.townydistricts.model.Cell(world,0,0);var district=new ru.neverland.townydistricts.model.District(UUID.randomUUID(),"native_like","Район",ru.neverland.townydistricts.model.DistrictType.RESIDENTIAL,Set.of(cell));var source=new ru.neverland.townydistricts.model.DistrictRules.Building("infirmary",world,0,0,15,15,1,1);var graph=new Input(List.of(district),List.of(source),Map.of("infirmary",ru.neverland.townydistricts.model.DistrictType.RESIDENTIAL),Set.of(cell),Set.of(world),cell,16,true,new Settings(8,Map.of(ru.neverland.townydistricts.model.DistrictType.RESIDENTIAL,List.of(new Need("medical","Медицина",Set.of("infirmary"))))));var actual=new DistrictPlanner();try(var guard=SuiteState.guard()){var underLock=ready(actual,UUID.randomUUID(),graph);check(underLock.status().equals("READY")&&underLock.result().rows().get("native_like").services().get(0).served()==1,"real nonempty district graph completes while another thread holds suite lock");}actual.awaitClosed();
        var bad=new DistrictPlanner(value->{throw new IllegalArgumentException("invalid source");});check(ready(bad,UUID.randomUUID(),input).status().equals("UNAVAILABLE"),"bad snapshot yields explicit unavailable instead of fabricated empty report");bad.awaitClosed();
        System.out.println("DistrictPlannerSmoke PASS "+checks+" checks");
    }
}
